function Shop() {
  function handleBuy(productId) {
    const result = document.querySelector('#result');
    result.textContent = productId + ' 구매';
  }

  return (
    <section>
      <button type="button" onClick={() => handleBuy('shirt')}>셔츠</button>
      <button type="button" onClick={() => handleBuy('hat')}>모자</button>
      <p id="result">상품을 선택하세요.</p>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Shop />);

